import {randomUUID} from 'node:crypto';
import {MongoMemoryServer} from 'mongodb-memory-server';
import {MongoClient} from 'mongodb';
import type {Collection, Db} from 'mongodb';
import type {MongoSessionDocument} from './mongoSessionDocument.js';

// A real mongod, started once per suite: no cloud account, no Docker, and no double standing in for a database.

const BINARY_DOWNLOAD_MS = 120_000;

export interface MongoHarness {
  db: Db;
  uri: string;
  dbName: string;
  stop: () => Promise<void>;
}

export const TEST_DB_NAME = 'hal-engine-test';

/** Starts a mongod for the surrounding suite and returns the handle its tests read through. */
export async function startMongo(): Promise<MongoHarness> {
  const server = await MongoMemoryServer.create();
  const client = new MongoClient(server.getUri());
  await client.connect();
  return {
    db: client.db(TEST_DB_NAME),
    uri: server.getUri(),
    dbName: TEST_DB_NAME,
    stop: async () => {
      await client.close();
      await server.stop();
    },
  };
}

/** A collection no other test writes to, so suites never have to clean up after each other. */
export function freshCollection(db: Db): Collection<MongoSessionDocument> {
  return db.collection<MongoSessionDocument>(`sessions_${randomUUID().replace(/-/g, '')}`);
}

/** The timeout the one-time mongod binary download needs, applied to `beforeAll` alone. */
export const MONGO_START_MS = BINARY_DOWNLOAD_MS;

/** Runs a mongod for the surrounding suite and hands each test a collection of its own. */
export function mongoCollection(): () => Collection<MongoSessionDocument> {
  let harness: MongoHarness;
  let collection: Collection<MongoSessionDocument>;

  beforeAll(async () => {
    harness = await startMongo();
  }, MONGO_START_MS);

  afterAll(() => harness.stop());

  beforeEach(() => {
    collection = freshCollection(harness.db);
  });

  return () => collection;
}

/** @type {import('ts-jest').JestConfigWithTsJest} */
export default {
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/scripts'],
  testMatch: ['**/*.test.ts'],
  // Fixture suites are inputs to the gate tests, not tests; one of them is deliberately skipped.
  testPathIgnorePatterns: ['/node_modules/', '/scripts/fixtures/'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleFileExtensions: ['ts', 'js', 'json'],
  // NodeNext source writes `./x.js` for `./x.ts`; jest resolves the real file.
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
  },
  transform: {
    '^.+\\.tsx?$': ['ts-jest', {useESM: true}],
  },
  // src/ only: the scripts/ suites drive their subjects through spawnSync, so an
  // instrumented .mjs would report zero regardless of how well it is tested.
  collectCoverageFrom: ['src/**/*.ts', '!src/**/*.test.ts', '!src/providers/providerTestSupport.ts', '!src/infrastructure/writeSignalTestSupport.ts', '!src/shared/logCaptureTestSupport.ts', '!src/transport/wsTestSupport.ts', '!src/infrastructure/stores/mongo/mongoTestSupport.ts'],
  // A ratchet, not a target: these are exactly what the suite measured when the
  // gate landed, so any drop fails and any rise should move them up with it. A
  // red run is fixed by adding the missing test, never by lowering the number
  // (specs/hal-engine-npm-release/spec.md).
  // The one exception: deleting covered code shrinks the denominator and lowers
  // the percentage while the uncovered count is unchanged. Compare covered/total
  // absolutes before re-baselining, and say so in the commit.
  // Per-path floors set at measurement, exactly as the global row is. An earlier version set them at
  // 70 with a comment claiming all four sat well above it - vertex's branches were 69.23, below it, and
